functions.showAdminTeamGuidance:
function showAdminTeamGuidance() {
  var TC_FILE = "team_commentary.enc.json";
  var TC_SECTION_KEY = "teamCommentary";

  function _ls(k) {
    try {
      return (window.eli && window.eli.compat && typeof window.eli.compat.lsGet === "function")
        ? (window.eli.compat.lsGet(k) || "") : "";
    } catch (_) { return ""; }
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _strToB64(s) {
    var bytes = new TextEncoder().encode(s);
    var bin = "";
    for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin);
  }
  function _mount(el) {
    if (typeof window._eliMountOverlay === "function") window._eliMountOverlay(el);
    else document.body.appendChild(el);
  }

  var _pat = _ls("eli_user_github_pat");
  var _cipher = _ls("eli_lib_cipher");
  var _repo = _ls("eli_github_repo") || "apndrewn/eli-data";
  var _branch = _ls("eli_github_branch") || "main";
  var _apiBase = "https://api.github.com/repos/" + _repo + "/contents/" + TC_FILE;
  var _ghHeaders = {
    "Authorization": "Bearer " + _pat,
    "Accept": "application/vnd.github+json",
    "X-GitHub-Api-Version": "2022-11-28",
  };

  // Mutable state for this session.
  var _envelope = null;     // the decrypted envelope (sections.teamCommentary[])
  var _sha = null;          // current GitHub file sha (for the PUT)
  var _rows = [];           // sections.teamCommentary rows
  var _pendingArchive = {}; // id -> true (queued for deletion)
  var _pendingEdit = {};    // id -> { text, tags } (queued edit)
  var _editingId = null;    // id currently open in the inline editor
  var _filter = "";
  var _showArchived = false; // archived entries hidden until toggled on

  // ─── Overlay scaffold ───────────────────────────────────────────────
  var existing = document.getElementById("adminTgOverlay");
  if (existing) existing.remove();
  var overlay = document.createElement("div");
  overlay.id = "adminTgOverlay";
  overlay.style.cssText =
    "position:fixed;inset:0;z-index:99999;background:rgba(15,23,42,0.6);" +
    "display:flex;align-items:center;justify-content:center;padding:20px;" +
    "font-family:Inter,'Segoe UI',system-ui,sans-serif;";
  var box = document.createElement("div");
  box.style.cssText =
    "background:#fff;width:min(860px,97vw);max-height:90vh;border:1px solid #cbd5e1;" +
    "box-shadow:0 24px 60px rgba(15,23,42,0.5);display:flex;flex-direction:column;overflow:hidden;";
  box.innerHTML =
    '<div style="padding:16px 22px;background:linear-gradient(135deg,#1e293b,#0f172a);color:#fff;display:flex;justify-content:space-between;align-items:flex-start;gap:12px;">' +
      '<div><div style="font-size:10px;font-weight:800;opacity:0.7;text-transform:uppercase;letter-spacing:1.4px;">🗂️ Team Guidance Admin</div>' +
      '<div style="font-size:16px;font-weight:800;margin-top:3px;">All published team guidance</div>' +
      '<div style="font-size:10.5px;opacity:0.72;margin-top:3px;">Decrypted from ' + _esc(_repo) + ' · edit or delete propagates to teammates on their next Review Redlines open</div></div>' +
      '<button id="adminTgClose" style="background:rgba(255,255,255,0.16);border:1px solid rgba(255,255,255,0.4);color:#fff;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer;border-radius:0;flex-shrink:0;">✕ Close</button>' +
    '</div>' +
    '<div style="padding:10px 22px;background:#f1f5f9;border-bottom:1px solid #e2e8f0;display:flex;gap:8px;align-items:center;">' +
      '<input id="adminTgSearch" type="text" placeholder="Filter by clause / section / author / text…" ' +
        'style="flex:1;padding:7px 10px;font-size:12px;border:1px solid #cbd5e1;border-radius:0;font-family:inherit;">' +
      '<label style="display:flex;align-items:center;gap:5px;font-size:11px;color:#475569;font-weight:600;cursor:pointer;white-space:nowrap;">' +
        '<input id="adminTgShowArchived" type="checkbox" style="cursor:pointer;margin:0;"> Show archived' +
      '</label>' +
      '<button id="adminTgRefresh" style="padding:7px 12px;font-size:11px;font-weight:700;background:#fff;border:1px solid #cbd5e1;color:#475569;cursor:pointer;border-radius:0;">↻ Refresh</button>' +
    '</div>' +
    '<div id="adminTgBody" style="flex:1;overflow-y:auto;padding:14px 22px;background:#f8fafc;font-size:12px;color:#1e293b;">' +
      '<div style="color:#94a3b8;font-style:italic;padding:20px 0;text-align:center;">Loading…</div>' +
    '</div>' +
    '<div style="padding:12px 22px;background:#f1f5f9;border-top:1px solid #cbd5e1;display:flex;gap:10px;justify-content:space-between;align-items:center;">' +
      '<div id="adminTgStatus" style="font-size:11px;color:#64748b;flex:1;min-width:0;"></div>' +
      '<button id="adminTgPublish" disabled style="padding:8px 16px;font-size:11px;font-weight:800;background:#1e3a8a;color:#fff;border:none;cursor:pointer;border-radius:0;opacity:0.45;letter-spacing:0.3px;">Publish changes</button>' +
    '</div>';
  overlay.appendChild(box);
  _mount(overlay);

  var bodyEl = box.querySelector("#adminTgBody");
  var statusEl = box.querySelector("#adminTgStatus");
  var publishBtn = box.querySelector("#adminTgPublish");
  var searchEl = box.querySelector("#adminTgSearch");
  var closeFn = function () { overlay.remove(); };
  box.querySelector("#adminTgClose").onclick = closeFn;
  overlay.onclick = function (e) { if (e.target === overlay) closeFn(); };

  function _setStatus(msg, color) {
    statusEl.innerHTML = '<span style="color:' + (color || "#64748b") + ';">' + _esc(msg) + '</span>';
  }
  function _refreshPublishBtn() {
    var nDel = Object.keys(_pendingArchive).length;
    // An edit on a row also queued for deletion is moot — don't double-count.
    var nEdit = Object.keys(_pendingEdit).filter(function (id) { return !_pendingArchive[id]; }).length;
    var n = nDel + nEdit;
    var parts = [];
    if (nEdit) parts.push(nEdit + " edit" + (nEdit === 1 ? "" : "s"));
    if (nDel) parts.push(nDel + " deletion" + (nDel === 1 ? "" : "s"));
    publishBtn.textContent = n === 0 ? "Publish changes" : ("Publish " + parts.join(" + "));
    publishBtn.disabled = n === 0;
    publishBtn.style.opacity = n === 0 ? "0.45" : "1";
    publishBtn.style.cursor = n === 0 ? "default" : "pointer";
    // Red signals the destructive deletion path; navy for edit-only.
    publishBtn.style.background = nDel ? "#b91c1c" : "#1e3a8a";
  }

  // ─── GitHub fetch + decrypt ─────────────────────────────────────────
  function _fetchRows() {
    // Fresh data invalidates any queued edits/deletions + open editor.
    _pendingArchive = {};
    _pendingEdit = {};
    _editingId = null;
    if (!_pat) {
      bodyEl.innerHTML = '<div style="color:#b91c1c;padding:20px 0;text-align:center;">No GitHub PAT set. Settings → Credentials → GitHub PAT.</div>';
      return;
    }
    if (!_cipher) {
      bodyEl.innerHTML = '<div style="color:#b91c1c;padding:20px 0;text-align:center;">No library cipher set. Settings → Credentials → Library Cipher.</div>';
      return;
    }
    bodyEl.innerHTML = '<div style="color:#94a3b8;font-style:italic;padding:20px 0;text-align:center;">Fetching + decrypting…</div>';
    // cache:"no-store" + a timestamp param — the GitHub contents API
    // sends Cache-Control, and a cached GET returns a STALE sha → the
    // next PUT 409s. Force a fresh read every time.
    fetch(_apiBase + "?ref=" + encodeURIComponent(_branch) + "&_ts=" + Date.now(),
        { headers: _ghHeaders, cache: "no-store" })
      .then(function (res) {
        if (res.status === 404) {
          // File not seeded yet — treat as empty.
          _envelope = { schemaVersion: 1, sectionVersions: {}, sections: {} };
          _envelope.sections[TC_SECTION_KEY] = [];
          _sha = null;
          _rows = [];
          _render();
          return null;
        }
        if (!res.ok) throw new Error("GitHub GET failed: " + res.status);
        return res.json();
      })
      .then(function (json) {
        if (!json) return;
        _sha = json.sha || null;
        var b64 = (json.content || "").replace(/\s/g, "");
        var blob;
        try { blob = JSON.parse(atob(b64)); } catch (e) { throw new Error("Could not parse the file."); }
        var p;
        if (blob && window._eliIsEncryptedBlob && window._eliIsEncryptedBlob(blob)) {
          if (typeof window._eliDecryptFromRepo !== "function") throw new Error("Decrypt helper unavailable (kernel).");
          p = window._eliDecryptFromRepo(_cipher, blob);
        } else if (blob && blob.sections) {
          p = Promise.resolve(blob); // plaintext envelope (seed)
        } else {
          throw new Error("Unrecognized file shape.");
        }
        return p.then(function (env) {
          _envelope = env || { schemaVersion: 1, sectionVersions: {}, sections: {} };
          _envelope.sections = _envelope.sections || {};
          _rows = Array.isArray(_envelope.sections[TC_SECTION_KEY])
            ? _envelope.sections[TC_SECTION_KEY] : [];
          _render();
        });
      })
      .catch(function (err) {
        bodyEl.innerHTML = '<div style="color:#b91c1c;padding:20px 0;text-align:center;">' +
          _esc((err && err.message) || "Failed to load.") +
          '<br><span style="color:#94a3b8;font-size:11px;">Check the PAT/cipher are correct for ' + _esc(_repo) + '.</span></div>';
      });
  }

  // ─── Render — grouped by clause (agreementType › article › section) ──
  function _render() {
    _refreshPublishBtn();
    var f = _filter.toLowerCase().trim();
    var visible = _rows.filter(function (r) {
      if (!r) return false;
      // Archived entries are hidden by default — shown only when the
      // "Show archived" toggle is on.
      if (r.status === "archived" && !_showArchived) return false;
      if (!f) return true;
      var hay = [r.agreementType, r.articleLabel, r.sectionLabel, r.authorName,
        r.text, (r.tags || []).join(" ")].join(" · ").toLowerCase();
      return hay.indexOf(f) !== -1;
    });
    var total = _rows.length;
    var activeCount = _rows.filter(function (r) { return r && r.status !== "archived"; }).length;
    var archivedCount = total - activeCount;
    _setStatus(total + " total · " + activeCount + " active · " + archivedCount + " archived" +
      (!_showArchived && archivedCount ? " (hidden)" : "") +
      (f ? " · " + visible.length + " shown" : ""));
    if (!visible.length) {
      bodyEl.innerHTML = '<div style="color:#94a3b8;font-style:italic;padding:20px 0;text-align:center;">' +
        (total ? "No entries match the filter." : "No team guidance has been published yet.") + '</div>';
      return;
    }
    // Group by clause key.
    var groups = {};
    var order = [];
    visible.forEach(function (r) {
      var key = (r.agreementType || "(no type)") + " › " +
        (r.articleLabel || "(no article)") + " › " + (r.sectionLabel || "(no section)");
      if (!groups[key]) { groups[key] = []; order.push(key); }
      groups[key].push(r);
    });
    order.sort();
    var html = "";
    order.forEach(function (key) {
      var rows = groups[key].slice().sort(function (a, b) {
        return String(b.createdAt || "").localeCompare(String(a.createdAt || ""));
      });
      html += '<div style="margin-bottom:14px;">' +
        '<div style="font-size:10px;font-weight:900;color:#0f172a;text-transform:uppercase;letter-spacing:0.08em;padding:4px 0;border-bottom:2px solid #1e293b;margin-bottom:4px;">' +
          _esc(key) + ' <span style="color:#94a3b8;font-weight:700;">(' + rows.length + ')</span></div>';
      rows.forEach(function (r) {
        var id = r.id || "";
        var archived = r.status === "archived";
        var queuedDelete = !!_pendingArchive[id];
        var pendingEdit = _pendingEdit[id] || null;
        var editing = _editingId === id;
        var when = r.createdAt ? String(r.createdAt).slice(0, 10) : "";
        // Pending-edit values win the display so the admin sees the result
        // before publishing.
        var effText = pendingEdit ? pendingEdit.text : (r.text || "");
        var effTags = pendingEdit ? pendingEdit.tags : (Array.isArray(r.tags) ? r.tags : []);
        var tagsHtml = (effTags && effTags.length)
          ? ' <span style="color:#0f766e;font-weight:700;">[' + _esc(effTags.join(", ")) + ']</span>' : '';
        var metaHtml = '<div style="font-size:10.5px;color:#475569;font-weight:700;">' + _esc(r.authorName || "(unknown)") +
          (when ? ' <span style="color:#94a3b8;font-weight:500;">· ' + _esc(when) + '</span>' : '') +
          tagsHtml +
          (archived ? ' <span style="color:#b45309;font-weight:800;">· ARCHIVED</span>' : '') +
          (pendingEdit ? ' <span style="color:#1e3a8a;font-weight:800;">· EDITED (pending)</span>' : '') +
          '</div>';

        // Inline editor — full-width textarea + tags + Save/Cancel.
        if (editing) {
          html += '<div data-tg-row="' + _esc(id) + '" style="padding:10px;background:#fff;border:1px solid #cbd5e1;' +
            'border-left:3px solid #1e3a8a;margin-bottom:4px;">' +
            metaHtml +
            '<textarea data-tg-edit-text="' + _esc(id) + '" style="width:100%;box-sizing:border-box;margin-top:6px;' +
              'min-height:74px;padding:7px 9px;font-size:12px;line-height:1.5;font-family:inherit;color:#1e293b;' +
              'border:1px solid #94a3b8;border-radius:0;resize:vertical;">' + _esc(effText) + '</textarea>' +
            '<input data-tg-edit-tags="' + _esc(id) + '" type="text" value="' + _esc((effTags || []).join(", ")) + '" ' +
              'placeholder="tags, comma-separated" style="width:100%;box-sizing:border-box;margin-top:6px;padding:6px 9px;' +
              'font-size:11px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;color:#475569;">' +
            '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:8px;">' +
              '<button data-tg-edit-cancel="' + _esc(id) + '" style="padding:5px 12px;font-size:11px;font-weight:700;' +
                'background:#fff;border:1px solid #cbd5e1;color:#475569;cursor:pointer;border-radius:0;">Cancel</button>' +
              '<button data-tg-edit-save="' + _esc(id) + '" style="padding:5px 14px;font-size:11px;font-weight:800;' +
                'background:#1e3a8a;border:none;color:#fff;cursor:pointer;border-radius:0;">Save edit</button>' +
            '</div>' +
          '</div>';
          return;
        }

        var leftColor = archived ? "#cbd5e1" : (queuedDelete ? "#b91c1c" : (pendingEdit ? "#1e3a8a" : "#0f766e"));
        var dimStyle = (archived || queuedDelete) ? "opacity:0.55;" : "";
        var textStyle = "font-size:12px;color:#1e293b;line-height:1.5;margin-top:2px;" +
          ((archived || queuedDelete) ? "text-decoration:line-through;" : "");

        var actionsHtml;
        if (archived) {
          actionsHtml = '<span style="font-size:10px;color:#94a3b8;font-style:italic;flex-shrink:0;padding-top:2px;">archived</span>';
        } else {
          var delBtn = '<button data-tg-del="' + _esc(id) + '" style="flex-shrink:0;padding:4px 10px;font-size:10px;' +
            'font-weight:800;background:' + (queuedDelete ? "#f1f5f9" : "#fee2e2") + ';border:1px solid ' +
            (queuedDelete ? "#cbd5e1" : "#fca5a5") + ';color:' + (queuedDelete ? "#475569" : "#b91c1c") + ';' +
            'cursor:pointer;border-radius:0;text-transform:uppercase;letter-spacing:0.4px;">' +
            (queuedDelete ? "Undo" : "Delete") + '</button>';
          // Edit affordance is suppressed while a row is queued for deletion.
          var editBtn = queuedDelete ? "" :
            '<button data-tg-edit-open="' + _esc(id) + '" style="flex-shrink:0;padding:4px 10px;font-size:10px;' +
            'font-weight:800;background:#eef2ff;border:1px solid #c7d2fe;color:#1e3a8a;cursor:pointer;border-radius:0;' +
            'text-transform:uppercase;letter-spacing:0.4px;">Edit</button>';
          var undoEditBtn = (pendingEdit && !queuedDelete)
            ? '<button data-tg-edit-undo="' + _esc(id) + '" style="flex-shrink:0;padding:4px 8px;font-size:10px;' +
              'font-weight:700;background:#fff;border:1px solid #cbd5e1;color:#64748b;cursor:pointer;border-radius:0;' +
              'text-transform:uppercase;letter-spacing:0.4px;">Undo edit</button>'
            : "";
          actionsHtml = '<div style="display:flex;flex-direction:column;gap:4px;flex-shrink:0;">' +
            editBtn + undoEditBtn + delBtn + '</div>';
        }

        html += '<div data-tg-row="' + _esc(id) + '" style="display:flex;gap:10px;align-items:flex-start;' +
          'padding:8px 10px;background:#fff;border:1px solid #e2e8f0;border-left:3px solid ' + leftColor +
          ';margin-bottom:4px;' + dimStyle + '">' +
          '<div style="flex:1;min-width:0;">' +
            metaHtml +
            '<div style="' + textStyle + '">' + _esc(effText) + '</div>' +
          '</div>' +
          actionsHtml +
        '</div>';
      });
      html += '</div>';
    });
    bodyEl.innerHTML = html;
    // Wire per-row Delete toggle.
    bodyEl.querySelectorAll("[data-tg-del]").forEach(function (btn) {
      btn.onclick = function () {
        var id = btn.getAttribute("data-tg-del");
        if (!id) return;
        if (_pendingArchive[id]) delete _pendingArchive[id];
        else {
          _pendingArchive[id] = true;
          delete _pendingEdit[id]; // a queued deletion supersedes any pending edit
          if (_editingId === id) _editingId = null;
        }
        _render();
      };
    });
    // Open the inline editor.
    bodyEl.querySelectorAll("[data-tg-edit-open]").forEach(function (btn) {
      btn.onclick = function () { _editingId = btn.getAttribute("data-tg-edit-open") || null; _render(); };
    });
    // Cancel the inline editor (no change queued).
    bodyEl.querySelectorAll("[data-tg-edit-cancel]").forEach(function (btn) {
      btn.onclick = function () { _editingId = null; _render(); };
    });
    // Save the inline editor → queue a pending edit.
    bodyEl.querySelectorAll("[data-tg-edit-save]").forEach(function (btn) {
      btn.onclick = function () {
        var id = btn.getAttribute("data-tg-edit-save");
        if (!id) return;
        var ta = bodyEl.querySelector('[data-tg-edit-text="' + id + '"]');
        var ti = bodyEl.querySelector('[data-tg-edit-tags="' + id + '"]');
        var newText = ta ? String(ta.value || "").trim() : "";
        if (!newText) { if (ta) ta.focus(); return; } // refuse to publish an empty guidance
        var newTags = ti
          ? String(ti.value || "").split(",").map(function (s) { return s.trim(); }).filter(Boolean)
          : [];
        var orig = null;
        for (var i = 0; i < _rows.length; i++) { if (_rows[i] && _rows[i].id === id) { orig = _rows[i]; break; } }
        var sameText = orig && String(orig.text || "") === newText;
        var sameTags = orig &&
          (Array.isArray(orig.tags) ? orig.tags : []).join("") === newTags.join("");
        // No net change vs the published row → don't queue it.
        if (sameText && sameTags) delete _pendingEdit[id];
        else _pendingEdit[id] = { text: newText, tags: newTags };
        _editingId = null;
        _render();
      };
    });
    // Undo a queued (not-yet-published) edit.
    bodyEl.querySelectorAll("[data-tg-edit-undo]").forEach(function (btn) {
      btn.onclick = function () { delete _pendingEdit[btn.getAttribute("data-tg-edit-undo")]; _render(); };
    });
  }

  // ─── Publish — apply queued edits + archives, re-encrypt, PUT ────────
  function _publish() {
    var delIds = Object.keys(_pendingArchive);
    // An edit on a row also queued for deletion is moot — deletion wins.
    var editIds = Object.keys(_pendingEdit).filter(function (id) { return !_pendingArchive[id]; });
    if ((!delIds.length && !editIds.length) || !_envelope) return;
    if (typeof window._eliEncryptForRepo !== "function") {
      _setStatus("Encrypt helper unavailable (kernel).", "#b91c1c");
      return;
    }
    publishBtn.disabled = true;
    publishBtn.style.opacity = "0.45";
    var summary = [];
    if (editIds.length) summary.push(editIds.length + " edit" + (editIds.length === 1 ? "" : "s"));
    if (delIds.length) summary.push(delIds.length + " deletion" + (delIds.length === 1 ? "" : "s"));
    var summaryText = summary.join(" + ");
    _setStatus("Publishing " + summaryText + " + pushing…", "#1e40af");
    var now = new Date().toISOString();
    var delSet = {};
    delIds.forEach(function (id) { delSet[id] = true; });
    var rows = _envelope.sections[TC_SECTION_KEY] || [];
    var changedRows = [];   // edited + archived rows (for local IDB mirror)
    rows.forEach(function (r) {
      if (!r || !r.id) return;
      if (delSet[r.id]) {
        r.status = "archived";
        r.updatedAt = now;        // newer than any teammate's copy → wins the merge
        r.syncState = "published";
        changedRows.push(r);
      } else if (_pendingEdit[r.id]) {
        var e = _pendingEdit[r.id];
        r.text = e.text;
        r.tags = e.tags;
        r.updatedAt = now;        // bump so the edit wins the additive merge
        r.syncState = "published";
        changedRows.push(r);
      }
    });
    _envelope.exportedAt = now;
    window._eliEncryptForRepo(_cipher, _envelope)
      .then(function (encrypted) {
        // Encrypt ONCE; retry the PUT on 409 with a fresh sha. A 409
        // means our cached sha was stale (GitHub served a cached GET, or
        // another writer landed first) — re-GET the head sha and retry.
        var content = _strToB64(JSON.stringify(encrypted, null, 2));
        var message = "Admin: " + summaryText + " — team guidance";

        function _refreshSha() {
          return fetch(_apiBase + "?ref=" + encodeURIComponent(_branch) + "&_ts=" + Date.now(),
              { headers: _ghHeaders, cache: "no-store" })
            .then(function (res) {
              if (res.status === 404) { _sha = null; return; }
              if (!res.ok) throw new Error("GitHub GET (sha refresh) failed: " + res.status);
              return res.json().then(function (j) { _sha = (j && j.sha) || null; });
            });
        }

        function _attempt(n) {
          var putBody = { message: message, content: content, branch: _branch };
          if (_sha) putBody.sha = _sha;
          return fetch(_apiBase, {
            method: "PUT",
            headers: Object.assign({}, _ghHeaders, { "Content-Type": "application/json" }),
            body: JSON.stringify(putBody),
          }).then(function (putRes) {
            if (putRes.status === 409 && n < 3) {
              return _refreshSha().then(function () { return _attempt(n + 1); });
            }
            if (!putRes.ok) {
              return putRes.text().then(function (t) {
                throw new Error("GitHub PUT failed: " + putRes.status + " " + String(t || "").slice(0, 120));
              });
            }
            return putRes.json();
          });
        }

        return _attempt(0);
      })
      .then(function (putJson) {
        _sha = (putJson && putJson.content && putJson.content.sha) || null;
        // Mirror into the admin's own local IDB so their Team Guidance
        // card + auditor reflect the edit/deletion immediately.
        if (window.eli && window.eli.storage && typeof window.eli.storage.put === "function") {
          changedRows.forEach(function (r) {
            try { window.eli.storage.put("team_commentary", r); } catch (_) {}
          });
        }
        _setStatus("✓ Published " + summaryText +
          " · teammates pick it up on their next Review Redlines open.", "#15803d");
        _pendingArchive = {};
        _pendingEdit = {};
        _editingId = null;
        _fetchRows(); // re-pull to show the updated state
      })
      .catch(function (err) {
        _setStatus("Publish failed: " + ((err && err.message) || "unknown"), "#b91c1c");
        _refreshPublishBtn();
      });
  }

  // ─── Wire controls ──────────────────────────────────────────────────
  publishBtn.onclick = _publish;
  box.querySelector("#adminTgRefresh").onclick = function () { _filter = searchEl.value || ""; _fetchRows(); };
  box.querySelector("#adminTgShowArchived").onchange = function () {
    _showArchived = !!this.checked;
    _render();
  };
  var _searchTimer = null;
  searchEl.oninput = function () {
    if (_searchTimer) clearTimeout(_searchTimer);
    _searchTimer = setTimeout(function () { _filter = searchEl.value || ""; _render(); }, 180);
  };

  _fetchRows();
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminTeamGuidance"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showAdminTeamGuidance !== "function") {
      eli.log.event("tool", "admin_team_guidance_fn_missing", {});
      if (typeof showToast === "function") showToast("Team Guidance Admin failed to load", "err");
      return;
    }
    try { window.showAdminTeamGuidance(); }
    catch (e) {
      eli.log.event("tool", "admin_team_guidance_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: { app_admin_team_guidance: _show },
    admin_team_guidance: { open: _show },
  });

  eli.log.event("tool", "admin_team_guidance_initialized", {});
}
